import{at as e,it as t,n,vt as r}from"./chunks/framework.B0lbOe_c.js";var i=JSON.parse(`{"title":"Portal","description":"","frontmatter":{"title":"Portal","covers":{"screens":["SCR-050","SCR-053"],"stories":["US-060","US-061","US-127","US-128"]}},"headers":[],"relativePath":"de/usage/portal.md","filePath":"de/usage/portal.md"}`),a={name:`de/usage/portal.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="portal" tabindex="-1">Portal <a class="header-anchor" href="#portal" aria-label="Permalink to “Portal”">​</a></h1><p>Das Portal zeigt die geteilten Kataloge und die Dashboards des Repositorys nur zum Lesen. Es ist für Leute gedacht, die die Architektur lesen, aber nicht daran arbeiten, zum Beispiel mit der Rolle <code>portal-reader</code>. Alle mit der Berechtigung <code>portal:read</code> können es öffnen; die Rollen <code>viewer</code>, <code>analyst</code> und <code>enterprise-architect</code> haben sie auch.</p><h2 id="das-portal-offnen" tabindex="-1">Das Portal öffnen <a class="header-anchor" href="#das-portal-offnen" aria-label="Permalink to “Das Portal öffnen”">​</a></h2><ul><li>Mit nur <code>portal:read</code> (zum Beispiel der Rolle <code>portal-reader</code>) landest du nach der Anmeldung im Portal. Die Kopfzeile zeigt <em>Portal</em> als einzigen Eintrag; auch die Startseite und die Kataloge führen ins Portal.</li><li>Mit <code>entity:read</code> zeigt die Kopfzeile <em>Portal</em> neben <em>Kataloge</em>.</li></ul><p>Die Seite <em>Portal</em> hat zwei Bereiche. <em>Geteilte Kataloge</em> listet die <strong>geteilten Kataloge</strong> nach Name, jeweils mit ihrem Entitätstyp; persönliche Kataloge erscheinen nie im Portal, auch deine eigenen nicht. <em>Dashboards</em> listet die <strong>Dashboards</strong> (siehe <a href="#dashboards">Dashboards im Portal</a>). Lässt sich eine Liste nicht laden, zeigt die Seite den Fehler in ihrem Bereich, und der andere Bereich bleibt benutzbar.</p><h2 id="einen-katalog-lesen" tabindex="-1">Einen Katalog lesen <a class="header-anchor" href="#einen-katalog-lesen" aria-label="Permalink to “Einen Katalog lesen”">​</a></h2><p>Wähle einen Katalog in der Liste. Er öffnet sich mit den Spalten, der Standardsortierung und dem Standard-Join-Modus, die seine Besitzerin oder sein Besitzer eingestellt hat.</p><ul><li><strong>Sortieren:</strong> Wähle eine Spaltenüberschrift. Der erste Klick sortiert aufsteigend, der zweite absteigend, der dritte stellt die Standardreihenfolge wieder her.</li><li><strong>Blättern:</strong> Die Tabelle zeigt 50 Zeilen pro Seite; mit den Seitenzahlen unter der Tabelle wechselst du die Seite.</li><li><strong>Zurück:</strong> <em>Zurück zum Portal</em> führt zur Liste.</li></ul><p>Sortierung und Seite stehen in der Adresse, du kannst eine sortierte Seite also als Lesezeichen speichern oder weitergeben. Das Portal bietet keine Aktion, die den Katalog ändert: keine Spalten, Joins, Filter, Ansichten und keinen Navigationsbaum. Ist ein Katalog nicht mehr geteilt oder gibt es ihn nicht, zeigt die Seite <em>Katalog nicht gefunden</em>.</p><p>Das Portal wendet wie jeder Katalog die <a href="./../administration/property-visibility">Sichtbarkeit von Eigenschaften</a> an: Eine Spalte zu einer Eigenschaft, die du nicht sehen darfst, bleibt leer, und eine Spalte zu einer verbindungsbasierten Eigenschaft zeigt den Wert nur in den Zeilen von Entitäten, die mit deinem Element verbunden sind. Mit einer <a href="./../administration/property-visibility#override-roles">Override-Rolle</a> siehst du alle Werte, und die Abfrage wird im Audit-Log festgehalten.</p><h2 id="dashboards" tabindex="-1">Dashboards <a class="header-anchor" href="#dashboards" aria-label="Permalink to “Dashboards”">​</a></h2><p>Der Bereich <em>Dashboards</em> listet nach Name die <strong>geteilten Dashboards</strong> und deine <strong>eigenen persönlichen Dashboards</strong>, jeweils mit der Anzahl ihrer Widgets; persönliche tragen das Kennzeichen <em>Persönlich</em>. Ein persönliches Dashboard einer anderen Person erscheint nie, auch nicht für Administratorinnen und Administratoren; sie lesen es im Arbeitsbereich (siehe <a href="./dashboards">Dashboards</a>). Ohne Dashboards steht im Bereich <em>Noch keine Dashboards.</em></p><p>Wähle ein Dashboard, um seine schreibgeschützte Ansicht zu öffnen:</p><ul><li>Die Widgets liegen dort, wo ihre Besitzerin oder ihr Besitzer sie im 12-Spalten-Raster platziert hat. Es gibt kein <em>Bearbeiten</em>, <em>Widget hinzufügen</em> oder <em>Löschen</em> und keinen Anfasser zum Verschieben oder Ändern der Größe; das Portal ändert nichts.</li><li>Die Widgets zeigen dieselben Daten wie im Arbeitsbereich, berechnet mit deinen Berechtigungen und der <a href="./../administration/property-visibility">Sichtbarkeit von Eigenschaften</a>: Ein KPI über eine Eigenschaft, die du nicht für alle Entitäten lesen darfst, sagt das, statt einen Wert zu zeigen, und ein Widget, das sich nicht berechnen lässt (zum Beispiel weil sein Katalog fehlt), zeigt seine Meldung, während die anderen normal erscheinen.</li><li>Ein Tabellen-Widget blättert mit <em>Seite x von y</em>. Seine Zeilen verlinken nicht auf eine Entität; das Portal hat noch keine Entitätsdetails.</li><li>Die Seite zeigt den Zeitpunkt der Daten (<em>Daten vom …</em>). <strong>Aktualisieren</strong> liest die Daten neu; die Seite aktualisiert sich nicht von selbst.</li><li><em>Zurück zum Portal</em> führt zur Liste. Gibt es das Dashboard nicht oder ist es für dich nicht sichtbar, sagt die Seite <em>Dashboard nicht gefunden</em>.</li></ul><p>Hast du nur <code>portal:read</code> und öffnest die Adresse eines Dashboards des Arbeitsbereichs (<code>/dashboards</code> oder <code>/dashboards/{id}</code>), wirst du ins Portal geleitet, oder zu demselben Dashboard im Portal.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><ul><li><code>GET /portal/catalogs</code> listet die geteilten Kataloge nach Name.</li><li><code>GET /portal/catalogs/{id}/query</code> liefert eine Seite eines geteilten Katalogs mit <code>page</code>, <code>pageSize</code> (höchstens 200) und <code>sort</code> (<code>{column}:{asc|desc}</code>), dasselbe Ergebnis wie <code>GET /catalogs/{id}/query</code> ohne Filter, abweichende Join-Modi oder Ansichten.</li><li>Die nächste Seite lässt sich mit <code>cursor</code> (dem <code>nextCursor</code> der vorherigen Seite) und <code>page</code> + 1 lesen, und eine Abfrage über der Zeitgrenze antwortet mit 503 <code>query-timeout</code>, wie bei der Katalogabfrage (siehe <a href="./catalogs#browse">Kataloge</a>). Ein Cursor der Katalogabfrage gilt im Portal nicht. Spalten zu Eigenschaften, die du nicht sehen darfst, sind leer, wie bei der Katalogabfrage.</li></ul><p>Beide brauchen <code>portal:read</code>. Ein persönlicher Katalog antwortet mit 404, ein ungültiger Parameter mit 400 und dem Parameter in <code>invalidFields</code>.</p><p>Die Dashboards des Portals brauchen nur <code>portal:read</code>:</p><ul><li><code>GET /portal/dashboards</code> listet die geteilten Dashboards und deine eigenen persönlichen nach Name, jeweils mit <code>canEdit: false</code>.</li><li><code>GET /portal/dashboards/{id}</code> liefert die Konfiguration (Widgets, Titel, Einstellungen und Rasterpositionen), <code>GET /portal/dashboards/{id}/data</code> die Daten aller Widgets und <code>GET /portal/dashboards/{id}/widgets/{widgetId}/data?page=</code> eine weitere Seite eines Tabellen-Widgets (ab 0; eine negative Seite antwortet mit 400). Die Antworten haben die Form der Lesezugriffe des Arbeitsbereichs (siehe <a href="./dashboards#api">Dashboards</a>), die Konfiguration immer mit <code>canEdit: false</code> und ohne <code>ETag</code>. Überschreitet die Katalogabfrage eines Tabellen-Widgets ihre Zeitgrenze, antwortet die Abfrage mit 503 <code>query-timeout</code>.</li><li>Das persönliche Dashboard einer anderen Person und ein unbekanntes Dashboard oder Widget antworten mit 404, auch für Administratorinnen und Administratoren. Servicekonten antworten mit 403.</li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};